  Future<void> _load() async {
    if (mounted) {
      setState(() {
        _loading = true;
        _error = '';
      });
    }
    try {
      final materials = await MobileApi.instance.calculateMaterials();
      if (!mounted) return;
      setState(() {
        _materials = materials;
        _loading = false;
      });
    } catch (error) {
      if (!mounted) return;
      setState(() {
        _loading = false;
        _error = _materialError(error, context.l10n);
